itChangedRows',count(*) FILTER(WHERE old_profit IS NOT NULL AND old_profit IS DISTINCT FROM new_profit),'previousKnownProfitDelta',sum(new_profit-old_profit) FILTER(WHERE old_profit IS NOT NULL),'privacy','Aggregates only; no source keys or customer fields returned') delta FROM compared;
